class Graph {
    int n;
    std::vector<std::vector<std::pair<int, int>>> adj;
public:
    Graph(int n, std::vector<std::vector<int>>& edges) : n(n), adj(n) {
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
        }
    }

    void addEdge(std::vector<int> edge) {
        adj[edge[0]].push_back({edge[1], edge[2]});
    }

    int shortestPath(int node1, int node2) {
        std::vector<int> dist(n, 1e9);
        dist[node1] = 0;
        std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<>> pq;
        pq.push({0, node1});
        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (u == node2) return d;
            if (d > dist[u]) continue;
            for (auto& [v, w] : adj[u]) {
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push({dist[v], v});
                }
            }
        }
        return -1;
    }
};

class Graph {
    private int n;
    private List<List<int[]>> adj;

    public Graph(int n, int[][] edges) {
        this.n = n;
        this.adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
        }
    }

    public void addEdge(int[] edge) {
        adj.get(edge[0]).add(new int[]{edge[1], edge[2]});
    }

    public int shortestPath(int node1, int node2) {
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[node1] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, node1});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], u = cur[1];
            if (u == node2) return d;
            if (d > dist[u]) continue;
            for (int[] edge : adj.get(u)) {
                int v = edge[0], w = edge[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.offer(new int[]{dist[v], v});
                }
            }
        }
        return -1;
    }
}

var Graph = function(n, edges) {
    this.n = n;
    this.adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        this.adj[u].push([v, w]);
    }
};

Graph.prototype.addEdge = function(edge) {
    const [u, v, w] = edge;
    this.adj[u].push([v, w]);
};

Graph.prototype.shortestPath = function(node1, node2) {
    const dist = new Array(this.n).fill(Infinity);
    dist[node1] = 0;
    const visited = new Set();
    for (let iter = 0; iter < this.n; iter++) {
        let u = -1;
        for (let i = 0; i < this.n; i++) {
            if (!visited.has(i) && (u === -1 || dist[i] < dist[u])) {
                u = i;
            }
        }
        if (u === -1 || dist[u] === Infinity) break;
        if (u === node2) return dist[u];
        visited.add(u);
        for (const [v, w] of this.adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
            }
        }
    }
    return dist[node2] === Infinity ? -1 : dist[node2];
};
